      const { app, calls } = buildApp({ onRefresh: async () => newAccessToken })
      const expired = await sign({ sub: 'user-2', exp: pastExp() }, accessSecret, 'HS256')
      const refreshToken = await sign(
        { sub: 'user-2', exp: futureExp() },
        refreshSecret,
        'HS256'
      )
      const req = new Request('http://localhost/auth/me', {
        headers: {
          Authorization: `Bearer ${expired}`,
          Cookie: `refresh_token=${refreshToken}`,
        },
      })
      const res = await app.request(req)
      expect(res.status).toBe(200)
      expect(res.headers.get('X-New-Access-Token')).toBe(newAccessToken)
      expect(await res.json()).toMatchObject({ sub: 'user-2', issued: 'refreshed' })
      expect(calls).toHaveLength(1)
      expect(calls[0]).toMatchObject({ sub: 'user-2' })
    })

    it('Should refresh when access token is missing and refresh token is valid', async () => {
      const newAccessToken = await sign(
        { sub: 'user-3', exp: futureExp() },
        accessSecret,
        'HS256'
      )
      const { app, calls } = buildApp({ onRefresh: async () => newAccessToken })
      const refreshToken = await sign(
        { sub: 'user-3', exp: futureExp() },
        refreshSecret,
        'HS256'
      )
      const req = new Request('http://localhost/auth/me', {
        headers: { Cookie: `refresh_token=${refreshToken}` },
      })
      const res = await app.request(req)
      expect(res.status).toBe(200)
      expect(res.headers.get('X-New-Access-Token')).toBe(newAccessToken)
      expect(calls).toHaveLength(1)
    })

    it('Should 401 when both tokens are invalid', async () => {
      const { app, calls } = buildApp({
        onRefresh: async () => {
          throw new Error('onRefresh should not be called')
        },
      })
      const expired = await sign({ sub: 'user-4', exp: pastExp() }, accessSecret, 'HS256')
      const badRefresh = await sign(
        { sub: 'user-4', exp: futureExp() },
        'wrong-refresh-secret',
        'HS256'
      )
      const req = new Request('http://localhost/auth/me', {
        headers: {
          Authorization: `Bearer ${expired}`,
          Cookie: `refresh_token=${badRefresh}`,
        },
      })
      const res = await app.request(req)
      expect(res.status).toBe(401)
      expect(calls).toHaveLength(0)
    })

    it('Should 401 without invoking onRefresh when access token has a bad signature', async () => {
      const { app, calls } = buildApp({
        onRefresh: async () => {
          throw new Error('onRefresh should not be called')
        },
      })
      const wrongSigToken = await sign(
        { sub: 'user-5', exp: futureExp() },
        'wrong-access-secret',
        'HS256'
      )
      const refreshToken = await sign(
        { sub: 'user-5', exp: futureExp() },
        refreshSecret,
        'HS256'
      )
      const req = new Request('http://localhost/auth/me', {
        headers: {
          Authorization: `Bearer ${wrongSigToken}`,
          Cookie: `refresh_token=${refreshToken}`,
        },
      })
      const res = await app.request(req)
      expect(res.status).toBe(401)
      expect(calls).toHaveLength(0)
    })

    it('Should 401 when both tokens are missing', async () => {
      const { app } = buildApp()
      const res = await app.request(new Request('http://localhost/auth/me'))
      expect(res.status).toBe(401)
    })

    it('Should 401 when authorization header is malformed', async () => {
      const { app } = buildApp()
      const req = new Request('http://localhost/auth/me', {
        headers: { Authorization: 'Basic something' },
      })
      const res = await app.request(req)
      expect(res.status).toBe(401)
      expect(res.headers.get('www-authenticate')).toContain('invalid_request')
    })

    it('Should respect a custom refreshCookie name', async () => {
      const newAccessToken = await sign(
        { sub: 'user-6', exp: futureExp() },
        accessSecret,
        'HS256'
      )
      const { app } = buildApp({
        refreshCookie: 'my_refresh',
        onRefresh: async () => newAccessToken,
      })
      const refreshToken = await sign(
        { sub: 'user-6', exp: futureExp() },
        refreshSecret,
        'HS256'
      )

      // Cookie under the default name must NOT trigger a refresh
      const reqDefault = new Request('http://localhost/auth/me', {
        headers: { Cookie: `refresh_token=${refreshToken}` },
      })
      const resDefault = await app.request(reqDefault)
      expect(resDefault.status).toBe(401)

      const reqCustom = new Request('http://localhost/auth/me', {
        headers: { Cookie: `my_refresh=${refreshToken}` },
      })
      const resCustom = await app.request(reqCustom)
      expect(resCustom.status).toBe(200)
      expect(resCustom.headers.get('X-New-Access-Token')).toBe(newAccessToken)
    })

    it('Should default refreshSecret to secret when not provided', async () => {
      const calls: unknown[] = []
      const app = new Hono()
      app.use(
        '/auth/*',
        jwtRefresh({
          secret: accessSecret,
          alg: 'HS256',
          onRefresh: async (payload) => {
            calls.push(payload)
            return await sign({ sub: 'user-7', exp: futureExp() }, accessSecret, 'HS256')
          },
        })
      )
      app.get('/auth/*', (c) => c.json(c.get('jwtPayload')))

      // Refresh token signed with the access secret since refreshSecret defaults to it
      const refreshToken = await sign(
        { sub: 'user-7', exp: futureExp() },
        accessSecret,
        'HS256'
      )
      const req = new Request('http://localhost/auth/me', {
        headers: { Cookie: `refresh_token=${refreshToken}` },
      })
      const res = await app.request(req)
      expect(res.status).toBe(200)
      expect(calls).toHaveLength(1)
      expect(res.headers.get('X-New-Access-Token')).toBeTruthy()
    })
  })
})

